Nit: Try methods in this library are generally implemented with the positive case first, e.g.
```C#
if (nodes.Count != 0)
{
    (element, priority) = this.nodes[RootIndex];
    Remove(RootIndex);
    return true;
}

element = default;
priority = default;
return false;
```

That's the existing behavior in `Queue.SetCapacity`, excerpt from there:

```
private void SetCapacity(int capacity)
{
    T[] newarray = new T[capacity];
    if (_size > 0)
    {
        if (_head < _tail)
        {
            Array.Copy(_array, _head, newarray, 0, _size);
        }
        else
        {
            Array.Copy(_array, _head, newarray, 0, _array.Length - _head);
            Array.Copy(_array, 0, newarray, _array.Length - _head, _tail);
        }
    }

    _array = newarray;
    _head = 0;
    _tail = (_size == capacity) ? 0 : _size;
    _version++;
}
```

This method (and consequently `_version++`) impacts public methids `TrimExcess`, `Enqueue` in `Queue`.

The `Stack<T>` one looks a lot simpler, as does `Queue<T>`. It should not be necessary to introduce any local variables.

How about this
```c#
            public struct Enumerator : IEnumerator<(TElement element, TPriority priority)>
            {
                private readonly PriorityQueue<TElement, TPriority> _queue;
                private readonly int _version;

                private int _index;   // -1 = not started, -2 = ended/disposed
                private (TElement element, TPriority priority)? _currentElement;

                internal Enumerator(PriorityQueue<TElement, TPriority> queue)
                {
                    _queue = queue;
                    _version = queue._version;
                    _index = -1;
                    _currentElement = default;
                }

                public (TElement element, TPriority priority) Current =>
                {
                    get
                    {
                        if (_index < 0)
                            ThrowEnumerationNotStartedOrEnded();
                        return _currentElement;
                    }
                }

                object? System.Collections.IEnumerator.Current => Current;

                public bool MoveNext()
                {
                    if (_version != _queue._version)
                       throw new InvalidOperationException(SR.InvalidOperation_EnumFailedVersion);

                    if (_index == -2) // ended
                        return false;

                    _index++;

                    if (_index < _queue._size)
                    {
                        _currentElement = _queue._nodes[_index];
                        return true;
                    }

                    _currentElement == default;
                    _index = -2;
                    return true;
                }

                void IEnumerator.Reset()
                {
                    if (_version != _queue._version)
                        throw new InvalidOperationException(SR.InvalidOperation_EnumFailedVersion);
                    _index = -1;
                    _currentElement = default;
                }

                public void Dispose()
                {
                    _index = -2;
                    _currentElement = default;
                }
     
                private void ThrowEnumerationNotStartedOrEnded() =>
                    throw new InvalidOperationException(_index == -1 ? SR.InvalidOperation_EnumNotStarted : SR.InvalidOperation_EnumEnded);
                }
            }
```

